ns16:scriptTask.ns16:script:
tw.local.requisition = {}; 
tw.local.requisition.date = new Date(new Date().getTime() + 1000*60*60*24*7);

tw.local.currentPosition = {};
tw.local.currentPosition.replacement = {};

tw.local.requisition.reqNum = "1141";
tw.local.requisition.requester = "Tom Miller";
tw.local.requisition.empNum = 1;
tw.local.requisition.department = "Finance";
tw.local.requisition.approvalNeeded = false;

//newly added to allow for full coach validation
tw.local.requisition.location = "Chicago";
tw.local.requisition.empType = "Contract";

tw.local.currentPosition.jobTitle = "Head of Product Development";
tw.local.currentPosition.replacement.lastName = "Smith";
tw.local.currentPosition.replacement.firstName = "Bob";
tw.local.currentPosition.replacement.supervisor = "Ann Fisher";
tw.local.currentPosition.replacement.payLevel = "8";
tw.local.currentPosition.replacement.payType = "Exempt";

tw.local.currentPosition.positionType = "New";
tw.local.currentPosition.replacement.notes = "";

function checkNumber(value) {
  return !isNaN(value) && parseInt(value) <= 0;
}

function checkString(value) {
  return value != null && value == "";
}

function checkDate(value) {
   var date = new Date();
   return value == null || ( date.getTime() > value.getTime() );
}

function checkList(value) {
  return value != null && value.length == 0;
}


if ( checkString(tw.local.currentPosition.positionType) ){
  tw.system.coachValidation.addValidationError("tw.local.currentPosition.positionType", "You must select a position type.");
}

if ( checkString(tw.local.requisition.location) ){
  tw.system.coachValidation.addValidationError("tw.local.requisition.location", "You must select a location.");
}


if ( checkDate(tw.local.requisition.date) ){
  tw.system.coachValidation.addValidationError("tw.local.requisition.date", "You must select a date that is in the future.");
}

if ( checkString(tw.local.requisition.empType) ){
  tw.system.coachValidation.addValidationError( "tw.local.requisition.empType", "You must select an employment type.");
}

if ( checkString(tw.local.requisition.department) ){
  tw.system.coachValidation.addValidationError("tw.local.requisition.department", "You must select a department.");
}

if ( checkNumber(tw.local.requisition.empNum) ){
	tw.system.coachValidation.addValidationError("tw.local.requisition.empNum", "Number of employees must be above 0.");
}

if ( checkList(tw.local.currentPosition.qualifications.education) ){
	tw.system.coachValidation.addValidationError("tw.local.currentPosition.qualifications.education[]", "You must select an education.");
}

if ( checkList(tw.local.currentPosition.qualifications.skills) ){
	tw.system.coachValidation.addValidationError("tw.local.currentPosition.qualifications.skills[]", "You must select a skill.");
}
